package com.votehub.repository; import com.votehub.entity.*; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; import java.util.*; public interface VoteRepository extends JpaRepository<Vote,Long>{long countByElectionId(Long id); @Query("select v.candidate.id, count(v) from Vote v where v.election.id=:eid group by v.candidate.id") List<Object[]> counts(@Param("eid") Long id);}
